{
  "prompt": "Create an 8-second 9:16 portrait video of the selected avatar speaking naturally to the camera as a friendly mobile phone salesperson. The avatar should wear a clean white T-shirt and stand inside a modern smartphone showroom with premium phones displayed on shelves in the background. Use the uploaded image as the exact reference for the iPhone 17. The avatar must hold, demonstrate, and promote the same iPhone 17 shown in the uploaded image. Keep the phone's design, color, camera layout, size, and all visible details highly consistent throughout the video. Show the uploaded iPhone 17 prominently in every scene. Use soft professional lighting, realistic facial expressions, natural eye contact, accurate lip sync, and a confident, welcoming tone. Do not display any on-screen text, captions, logos, watermarks, branding, price tags, banners, or store names anywhere in the video.\n\nScript:\n\"Looking for the all-new iPhone 17? Experience its stunning design, powerful performance, and incredible camera. Visit our store today and take home your new iPhone 17!\"",
  "avatarName": "me",
  "mediaUrl": "https://m.media-amazon.com/images/I/616-Eh2FbPL._AC_UF1000,1000_QL80_AIweblab1380616,T1_.jpg",
  "settings": {
    "aspectRatio": "9:16",
    "model": "Omni 1.1 Flash",
    "duration": 8
  }
}
